import Foundation
import NLLBNative
import Testing

private let marianFolder = ProcessInfo.processInfo.environment["EARMARK_MARIAN_MODEL_DIR"]

/// Goldens generated by CTranslate2 4.6.0 / SentencePiece 0.2.1 with the
/// pinned gaudi/opus-mt-en-de-ctranslate2 checkpoint in the research inventory.
/// These catch missing source EOS and accidental reuse of NLLB language tags.
@Suite("Marian native parity", .serialized, .enabled(if: marianFolder != nil))
struct MarianNativeTests {
    @Test func matchesPinnedReference() throws {
        let model = try NativeNLLBModel(
            folder: URL(fileURLWithPath: #require(marianFolder)), profile: .marian)
        #expect(try model.translate("The meeting starts tomorrow morning.", source: "en", target: "de") == "Das Treffen beginnt morgen früh.")
        #expect(try model.translate("Hello world.", source: "en", target: "de") == "Hallo Welt.")
    }

    @Test func refusesOversizedInputRatherThanTruncating() throws {
        let model = try NativeNLLBModel(
            folder: URL(fileURLWithPath: #require(marianFolder)), profile: .marian)
        #expect(throws: NativeNLLBError.self) {
            try model.translate(String(repeating: "meeting ", count: 600), source: "en", target: "de")
        }
    }
}
